const VARIABLE_SEARCH_VALUE = /{([^}]+)}/g;

// Prefix of every request URL generated by the spec importers (OpenAPI 3 and Swagger 2).
export const REQUEST_BASE_URL = '{{ _.base_url }}';

export const pathWithParamsAsPathParameters = (path?: string) => path?.replace(VARIABLE_SEARCH_VALUE, ':$1') ?? '';

export const pathWithParamsAsVariables = (path?: string) => path?.replace(VARIABLE_SEARCH_VALUE, '{{ _.$1 }}');
